{"tool": "write", "path": "reports/export.py", "content": """"Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""


def _quote_field(field):
    """Apply RFC 4180 minimal quoting and quote doubling to a string field."""
    if any(ch in field for ch in ',"\r\n'):
        return '"' + field.replace('"', '""') + '"'
    return field


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    ``rows`` is an iterable of mappings; ``columns`` is an ordered iterable of
    unique string column names. Returns a str with a CSV header followed by one
    record per row, comma delimiters, CRLF record endings, minimal quoting with
    quote doubling. Missing fields and None become empty strings; other values
    become str(value). Unselected fields are ignored. Inputs are not mutated.
    """
    cols = list(columns)  # copy so one-shot generators / iterators work
    seen = set()
    for name in cols:
        if not isinstance(name, str):
            raise ValueError("column names must be strings: %r" % (name,))
        if name in seen:
            raise ValueError("duplicate column name: %r" % (name,))
        seen.add(name)

    lines = [",".join(_quote_field(name) for name in cols)]
    for row in rows:
        fields = []
        for name in cols:
            try:
                value = row[name]
            except KeyError:
                value = ""
            if value is None:
                value = ""
            else:
                value = str(value)
            fields.append(_quote_field(value))
        lines.append(",".join(fields))
    return "\r\n".join(lines) + "\r\n"
